export function scheduleRetry(orderId: string, attempt: number): void {
  if (attempt > MAX_ATTEMPTS) {
    paymentRetryQueue.delete(orderId);
    return;
  }
  paymentRetryQueue.set(orderId, Date.now() + backoffDelay(attempt));
}

